<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';
import CvBankPagination from './CvBankPagination.vue';
import CvBankSettings from './CvBankSettings.vue';
defineProps<{csrf?:string|null}>();
const section=ref(sessionStorage.getItem('cv-bank-section')||'applications'),search=ref(''),data=ref<any>({jobs:[],applications:[],departments:[]}),loading=ref(true),error=ref('');
const page=ref(1),pageSize=ref(6),jobSearch=ref(''),jobStatus=ref('all');
const jobView=ref(localStorage.getItem('cv-bank-job-view')==='list'?'list':'grid');
const departmentDialog=ref<HTMLDialogElement|null>(null),departmentEditing=ref<any>(null);
function openDepartment(department:any=null){departmentEditing.value=department?{...department}:{name:'',active:true};departmentDialog.value?.showModal();}
const jobDialog=ref<HTMLDialogElement|null>(null);
function openCreateJob(){jobDialog.value?.showModal();}
watch(jobView,value=>localStorage.setItem('cv-bank-job-view',value));
const editing=ref<any>(null),editDialog=ref<HTMLDialogElement|null>(null);
function editApplication(application:any){editing.value=application;editDialog.value?.showModal();}
function appliedDate(value:string){return new Intl.DateTimeFormat(undefined,{dateStyle:'medium'}).format(new Date(value));}
const selectedDepartment=ref<string|null>(null),preview=ref<any>(null),previewDialog=ref<HTMLDialogElement|null>(null);
function openPreview(application:any){preview.value=application;previewDialog.value?.showModal();}
const departmentCards=computed(()=>Array.from(new Set<string>([...data.value.departments.map((d:any)=>d.name),...data.value.applications.map((a:any)=>a.department)])).sort().map(name=>({name,count:data.value.applications.filter((a:any)=>a.department===name).length})));
watch(section,value=>sessionStorage.setItem('cv-bank-section',value));
const applications=computed(()=>data.value.applications.filter((a:any)=>(selectedDepartment.value===null||a.department===selectedDepartment.value)&&`${a.name} ${a.email} ${a.department} ${a.job_title||''}`.toLowerCase().includes(search.value.toLowerCase())));
const filteredDepartmentCards=computed(()=>departmentCards.value.filter(d=>d.name.toLowerCase().includes(search.value.toLowerCase())));
const jobs=computed(()=>data.value.jobs.filter((job:any)=>`${job.title} ${job.department}`.toLowerCase().includes(jobSearch.value.toLowerCase())&&(jobStatus.value==='all'||Boolean(job.active)===(jobStatus.value==='active'))));
const activeItems=computed(()=>section.value==='jobs'?jobs.value:section.value==='departments'?data.value.departments:selectedDepartment.value===null?filteredDepartmentCards.value:applications.value);
const paginatedItems=computed(()=>activeItems.value.slice((page.value-1)*pageSize.value,page.value*pageSize.value));
watch([section,selectedDepartment,search,jobSearch,jobStatus,pageSize],()=>{page.value=1});
function jobApplicationCount(id:number){return data.value.applications.filter((a:any)=>a.job_id===id).length;}
onMounted(async()=>{try{const response=await fetch('/cv-bank/data',{headers:{Accept:'application/json'}});if(!response.ok)throw new Error('Unable to load CV Bank.');data.value=await response.json();if(section.value==='settings'&&!data.value.can_edit_careers)section.value='applications';}catch(e:any){error.value=e.message;}finally{loading.value=false;}});
</script>
<template><section class="cv-workspace"><header class="cv-heading"><div><p class="eyebrow">JUDIBAS / RECRUITMENT</p><h1>CV Bank</h1><p class="muted">Manage opportunities and find the right people for your team.</p></div><a class="button" href="/careers" target="_blank" rel="noopener">View careers page ↗</a></header><div class="cv-layout"><nav class="cv-nav" aria-label="CV Bank navigation"><button :class="{active:section==='applications'}" @click="section='applications'">Applications <span>{{data.applications.length}}</span></button><button :class="{active:section==='jobs'}" @click="section='jobs'">Jobs <span>{{data.jobs.length}}</span></button><button :class="{active:section==='departments'}" @click="section='departments'">Departments <span>{{data.departments.length}}</span></button><button v-if="data.can_edit_careers" :class="{active:section==='settings'}" @click="section='settings'">Settings <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="m9 3-1 3-3 1-2 4 2 2v4l4 2 3-1 3 1 4-2v-4l2-2-2-4-3-1-1-3z"/><circle cx="12" cy="12" r="3"/></svg></button><a href="/products">← All products</a></nav><div class="cv-content"><p v-if="loading" class="muted">Loading CV Bank…</p><p v-else-if="error" role="alert">{{error}}</p><template v-else-if="section==='applications'"><div class="cv-section-heading"><div><h2>{{selectedDepartment||'Applications'}}</h2><p class="muted">Review candidates by department and opportunity.</p></div><input v-model="search" :placeholder="selectedDepartment===null?'Search departments':'Search candidates'" aria-label="Search applications"></div><div v-if="selectedDepartment===null" class="cv-department-grid"><button v-for="department in filteredDepartmentCards" :key="department.name" class="cv-department-card" @click="selectedDepartment=department.name;search=''"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M3 21V3h12v18M15 9h6v12M7 7h4M7 11h4M7 15h4M1 21h22"/></svg><strong>{{department.name}}</strong><span class="muted">{{department.count}} {{department.count===1?'application':'applications'}}</span><span class="cv-department-link">View applications &rarr;</span></button></div><template v-else><button class="button cv-back" @click="selectedDepartment=null;search=''">&larr; All departments</button><div class="cv-applications-list"><article v-for="a in paginatedItems" :key="a.id" class="cv-application-row"><div class="cv-person-avatar" aria-hidden="true">{{a.name.split(' ').slice(0,2).map((word:string)=>word[0]).join('')}}</div><div class="cv-person-summary"><button class="cv-person-name" @click="editApplication(a)">{{a.name}}</button><p class="muted">{{a.job_title||'General application'}}</p><a class="cv-person-email" :href="'mailto:'+a.email">{{a.email}}</a></div><div class="cv-application-meta"><span class="cv-status" :class="'cv-status-'+a.status">{{a.status==='new'?'New':a.status.charAt(0).toUpperCase()+a.status.slice(1)}}</span><time class="muted" :datetime="a.created_at">Applied {{appliedDate(a.created_at)}}</time></div><div class="cv-actions"><button class="button primary" @click="openPreview(a)">View CV</button><button class="button" @click="editApplication(a)">Review</button><a class="cv-download-icon button" :href="'/cv-bank/applications/'+a.id+'/cv'" :aria-label="'Download CV for '+a.name" title="Download CV"><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/></svg></a></div></article></div><div v-if="!applications.length" class="cv-card cv-empty"><h3>{{search?'No matching applications':'Your candidate pool starts here'}}</h3><p class="muted">{{search?'Try another name or department.':'Share your careers page to receive CVs and general applications.'}}</p></div></template></template><template v-else-if="section==='jobs'">
<div class="cv-section-heading"><div><h2>Jobs</h2><p class="muted">Manage opportunities published on your careers page.</p></div><button class="button primary" @click="openCreateJob"><span aria-hidden="true">+</span> Create job</button></div>
<div class="cv-jobs-toolbar"><input v-model="jobSearch" placeholder="Search jobs or departments" aria-label="Search jobs"><select v-model="jobStatus" aria-label="Filter job status"><option value="all">All statuses</option><option value="active">Active</option><option value="archived">Archived</option></select><div class="cv-view-toggle" role="group" aria-label="Job display"><button :class="{active:jobView==='grid'}" :aria-pressed="jobView==='grid'" @click="jobView='grid'"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z"/></svg>Grid</button><button :class="{active:jobView==='list'}" :aria-pressed="jobView==='list'" @click="jobView='list'"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M3 5h2m3 0h13M3 12h2m3 0h13M3 19h2m3 0h13"/></svg>List</button></div></div>
<div class="cv-jobs" :class="'cv-jobs-'+jobView"><article v-for="job in paginatedItems" :key="job.id" class="cv-job-card"><div class="cv-job-card-heading"><span class="cv-job-icon" aria-hidden="true"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M8 7V4h8v3M3 7h18v14H3zM3 12c6 4 12 4 18 0M10 13h4v4h-4z"/></svg></span><span class="cv-status" :class="job.active?'cv-status-hired':'cv-status-rejected'">{{job.active?'Active':'Archived'}}</span></div><div class="cv-job-summary"><p class="cv-job-department">{{job.department}}</p><h3>{{job.title}}</h3><p class="cv-job-description muted">{{job.description||'No description added.'}}</p></div><div class="cv-job-facts"><span>{{jobApplicationCount(job.id)}} {{jobApplicationCount(job.id)===1?'application':'applications'}}</span><time :datetime="job.created_at">Created {{appliedDate(job.created_at)}}</time></div><footer class="cv-job-footer"><button class="cv-job-link" @click="section='applications';selectedDepartment=job.department;search=job.title">View applications &rarr;</button><form v-if="job.active" method="post" :action="'/cv-bank/jobs/'+job.id"><input type="hidden" name="_token" :value="csrf"><input type="hidden" name="_method" value="DELETE"><button class="button">Archive</button></form><form v-else method="post" :action="'/cv-bank/jobs/'+job.id+'/restore'"><input type="hidden" name="_token" :value="csrf"><button class="button primary">Restore job</button></form></footer></article></div><div v-if="!jobs.length" class="cv-card cv-empty"><h3>{{jobSearch||jobStatus!=='all'?'No matching jobs':'Your next hire starts here'}}</h3><p class="muted">{{jobSearch||jobStatus!=='all'?'Try a different search or status filter.':'Create a job to publish an opportunity on your careers page.'}}</p></div>
</template><template v-else-if="section==='departments'"><div class="cv-section-heading"><div><h2>Departments</h2><p class="muted">Organise roles and applications into your recruitment teams.</p></div><button class="button primary" @click="openDepartment()">+ Create department</button></div><div class="cv-department-notice">Active departments appear on the careers page and in job creation. Inactive departments remain available for reviewing existing applications.</div><div v-if="data.departments.length" class="cv-departments-list"><article v-for="d in paginatedItems" :key="d.id" class="cv-department-row"><span class="cv-job-icon" aria-hidden="true"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M3 21V3h12v18M15 9h6v12M7 7h4M7 11h4M7 15h4M1 21h22"/></svg></span><div class="cv-department-name"><h3>{{d.name}}</h3><p class="muted">{{data.jobs.filter((j:any)=>j.department===d.name).length}} jobs &middot; {{data.applications.filter((a:any)=>a.department===d.name).length}} applications</p></div><span class="cv-status" :class="d.active?'cv-status-hired':'cv-status-rejected'">{{d.active?'Active':'Inactive'}}</span><button class="button" @click="openDepartment(d)">Edit department</button></article></div><div v-else class="cv-card cv-empty"><h3>Build your recruitment teams</h3><p class="muted">Create your first department to start publishing jobs and receiving CVs.</p><button class="button primary" @click="openDepartment()">Create department</button></div></template><template v-else-if="section==='settings'&&data.can_edit_careers"><CvBankSettings :data="data" :csrf="csrf" @published="(settings)=>{data.career_settings={...data.career_settings,...settings};if(settings.career_editors)data.career_editors=settings.career_editors}"/></template><CvBankPagination v-if="section!=='settings'&&!loading&&!error&&(section!=='applications'||selectedDepartment!==null)" v-model:page="page" v-model:page-size="pageSize" :total="activeItems.length"/></div></div><dialog ref="departmentDialog" class="cv-edit-dialog" @click="(event)=>{if(event.target===departmentDialog)departmentDialog?.close()}" @close="departmentEditing=null"><template v-if="departmentEditing"><header class="cv-preview-heading"><div><p class="eyebrow">RECRUITMENT TEAMS</p><h3>{{departmentEditing.id?'Edit department':'Create department'}}</h3><p class="muted">Manage where candidates can apply.</p></div><button type="button" class="cv-modal-close" aria-label="Close department form" @click="departmentDialog?.close()"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button></header><form method="post" action="/cv-bank/departments" class="cv-edit-body cv-edit-form"><input type="hidden" name="_token" :value="csrf"><input v-if="departmentEditing.id" type="hidden" name="id" :value="departmentEditing.id"><label>Department name<input name="name" :value="departmentEditing.name" required maxlength="100" placeholder="e.g. Design"></label><label>Availability<select name="active" :value="departmentEditing.active?1:0"><option :value="1">Active</option><option :value="0">Inactive</option></select></label><p class="muted">Only active departments accept new applications and jobs.</p><div class="cv-edit-footer"><button type="button" class="button" @click="departmentDialog?.close()">Cancel</button><button class="button primary">{{departmentEditing.id?'Save changes':'Create department'}}</button></div></form></template></dialog><dialog ref="jobDialog" class="cv-edit-dialog" @click="(event)=>{if(event.target===jobDialog)jobDialog?.close()}"><header class="cv-preview-heading"><div><p class="eyebrow">NEW OPPORTUNITY</p><h3>Create job</h3><p class="muted">Add the role and department to your careers page.</p></div><button type="button" class="cv-modal-close" aria-label="Close job creation" @click="jobDialog?.close()"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button></header><form action="/cv-bank/jobs" method="post" class="cv-edit-body cv-job-form"><input type="hidden" name="_token" :value="csrf"><div class="cv-fields"><label>Job title<input name="title" required maxlength="160" placeholder="e.g. Graphic Designer"></label><label>Department<select name="department" required><option value="">Select department</option><option v-for="d in data.departments.filter((d:any)=>d.active)" :key="d.id" :value="d.name">{{d.name}}</option></select></label></div><label>Description<textarea name="description" rows="4" maxlength="5000" placeholder="Describe the opportunity and requirements"></textarea></label><p v-if="!data.departments.some((d:any)=>d.active)" class="muted">Create an active department before publishing a job.</p><div class="cv-edit-footer"><button type="button" class="button" @click="jobDialog?.close()">Cancel</button><button class="button primary" :disabled="!data.departments.some((d:any)=>d.active)">Publish job</button></div></form></dialog><dialog ref="editDialog" class="cv-edit-dialog" @click="(event)=>{if(event.target===editDialog)editDialog?.close()}" @close="editing=null"><template v-if="editing"><header class="cv-preview-heading"><div><p class="eyebrow">APPLICATION REVIEW</p><h3>{{editing.name}}</h3><p class="muted">{{editing.department}} &middot; {{editing.job_title||'General application'}}</p></div><button type="button" class="cv-modal-close" aria-label="Close application review" @click="editDialog?.close()"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button></header><div class="cv-edit-body"><div class="cv-review-contact"><a :href="'mailto:'+editing.email">{{editing.email}}</a><span v-if="editing.phone">{{editing.phone}}</span><span class="muted">Applied {{appliedDate(editing.created_at)}}</span></div><div v-if="editing.cover_letter" class="cv-cover-letter"><h4>Cover letter</h4><p>{{editing.cover_letter}}</p></div><form method="post" :action="'/cv-bank/applications/'+editing.id" class="cv-edit-form"><input type="hidden" name="_token" :value="csrf"><input type="hidden" name="_method" value="PATCH"><label>Application status<select name="status" :value="editing.status"><option value="new">New</option><option value="reviewing">Reviewing</option><option value="shortlisted">Shortlisted</option><option value="rejected">Rejected</option><option value="hired">Hired</option></select></label><label>Internal notes<textarea name="notes" :value="editing.notes" rows="4" placeholder="Add feedback or next steps for your team"></textarea></label><div class="cv-edit-footer"><button type="button" class="button" @click="editDialog?.close()">Cancel</button><button class="button primary">Save changes</button></div></form></div></template></dialog><dialog ref="previewDialog" class="cv-preview-dialog" @click="(event)=>{if(event.target===previewDialog)previewDialog?.close()}" @close="preview=null"><template v-if="preview"><header class="cv-preview-heading"><div><h3>{{preview.name}}</h3><p class="muted">CV preview</p></div><div class="cv-actions"><a class="button" :href="'/cv-bank/applications/'+preview.id+'/cv'">Download CV</a><button type="button" class="cv-modal-close" aria-label="Close CV preview" @click="previewDialog?.close()"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div></header><iframe :src="'/cv-bank/applications/'+preview.id+'/preview'" :title="'CV for '+preview.name"></iframe></template></dialog></section></template>
<style scoped>
.cv-department-notice{color:var(--muted);font-size:13px;line-height:1.7;margin-top:24px;padding:14px 18px;background:var(--rail);border:1px solid var(--line);border-radius:10px}.cv-departments-list{margin-top:20px;border:1px solid var(--line);border-radius:14px;background:var(--rail);overflow:hidden}.cv-department-row{display:flex;align-items:center;gap:20px;padding:22px;border-bottom:1px solid var(--line)}.cv-department-row:last-child{border:0}.cv-department-name{flex:1;min-width:0}.cv-department-name h3{overflow-wrap:anywhere}.cv-department-name p{margin:6px 0 0;font-size:12px}.cv-empty>.button{margin-top:18px}@media(max-width:550px){.cv-department-row{flex-wrap:wrap;padding:18px;gap:12px}.cv-department-row>.button{margin-left:54px}.cv-department-name{min-width:100px}}

.cv-jobs-toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:24px 0 20px}.cv-jobs-toolbar>input{flex:1;min-width:180px;max-width:360px}.cv-jobs-toolbar>select{width:auto;min-width:145px}.cv-view-toggle{display:flex;gap:4px;background:var(--rail);border:1px solid var(--line);border-radius:9px;padding:4px;margin-left:auto}.cv-view-toggle button{display:flex;align-items:center;gap:7px;background:none;color:var(--muted);border:0;border-radius:6px;padding:9px 12px;font:inherit;cursor:pointer}.cv-view-toggle button.active{background:var(--bg);color:var(--text);box-shadow:0 1px 5px #0001}.cv-jobs{display:grid;gap:18px}.cv-jobs-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.cv-job-card{border:1px solid var(--line);border-radius:14px;background:var(--rail);padding:22px;min-width:0;display:flex;flex-direction:column;gap:18px}.cv-job-card-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}.cv-job-icon{display:grid;place-items:center;width:42px;height:42px;border-radius:11px;background:#7563e820;color:#9585ff}.cv-job-department{font-size:11px;text-transform:uppercase;letter-spacing:.7px;color:#9585ff;margin:0 0 8px}.cv-job-summary h3{overflow-wrap:anywhere;font-size:18px}.cv-job-description{line-height:1.6;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;margin:10px 0 0}.cv-job-facts{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;font-size:12px;color:var(--muted);margin-top:auto}.cv-job-footer{border-top:1px solid var(--line);padding-top:16px;display:flex;justify-content:space-between;align-items:center;gap:12px}.cv-job-link{color:#9585ff;background:none;border:0;padding:0;text-align:left;font:inherit;font-size:13px;cursor:pointer}.cv-job-link:hover{text-decoration:underline}.cv-job-footer .muted{font-size:12px}.cv-jobs-list .cv-job-card{display:grid;grid-template-columns:130px minmax(0,1fr) 180px;align-items:center;gap:20px}.cv-jobs-list .cv-job-facts{margin:0;flex-direction:column}.cv-jobs-list .cv-job-footer{grid-column:2/-1}.cv-jobs-list .cv-job-description{-webkit-line-clamp:1}@media(min-width:1500px){.cv-jobs-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:850px){.cv-jobs-list .cv-job-card{grid-template-columns:100px minmax(0,1fr)}.cv-jobs-list .cv-job-facts{grid-column:2}.cv-jobs-list .cv-job-card-heading{flex-wrap:wrap}}@media(max-width:550px){.cv-jobs-grid{grid-template-columns:1fr}.cv-jobs-toolbar>input{max-width:none}.cv-view-toggle{margin-left:0}.cv-job-card{padding:18px}.cv-jobs-list .cv-job-card{display:flex;align-items:stretch}.cv-jobs-list .cv-job-card-heading{flex-wrap:nowrap}.cv-jobs-list .cv-job-facts{flex-direction:row}}

.cv-applications-list{margin-top:18px;border:1px solid var(--line);border-radius:14px;overflow:hidden;background:var(--rail)}.cv-application-row{display:flex;align-items:center;gap:18px;padding:22px;border-bottom:1px solid var(--line)}.cv-application-row:last-child{border-bottom:0}.cv-person-avatar{width:44px;height:44px;flex-shrink:0;display:grid;place-items:center;border-radius:12px;color:#a699ff;background:#7563e820;font-weight:700}.cv-person-summary{flex:1;min-width:0}.cv-person-name{border:0;padding:0;background:none;color:var(--text);font:inherit;font-weight:600;text-align:left;cursor:pointer}.cv-person-name:hover{text-decoration:underline}.cv-person-summary p{margin:5px 0;font-size:13px}.cv-person-email{font-size:12px;color:var(--muted);overflow-wrap:anywhere}.cv-application-meta{display:grid;gap:10px;justify-items:start;min-width:140px}.cv-application-meta time{font-size:12px}.cv-status{display:inline-flex;align-items:center;gap:6px;padding:5px 9px;border-radius:6px;font-size:12px;background:#6b72801c;color:var(--muted)}.cv-status:before{content:'';width:5px;height:5px;border-radius:50%;background:currentColor}.cv-status-new{color:#749de8;background:#5286e519}.cv-status-reviewing{color:#ab91ed;background:#9462e51c}.cv-status-shortlisted{color:#daa74e;background:#d6a33a1c}.cv-status-hired{color:#49b887;background:#35aa781c}.cv-status-rejected{color:#dd7d7d;background:#d65b5b19}.cv-edit-dialog{width:min(620px,92vw);max-height:90vh;border:1px solid var(--line);padding:0;border-radius:14px;color:var(--text);background:var(--bg)}.cv-edit-dialog::backdrop{background:#0009}.cv-edit-body{padding:24px}.cv-edit-form{display:grid;gap:20px}.cv-review-contact{display:grid;gap:9px;font-size:13px;margin-bottom:24px}.cv-cover-letter{border-top:1px solid var(--line);padding-top:18px;margin-bottom:22px}.cv-cover-letter h4{margin:0 0 10px}.cv-cover-letter p{color:var(--muted);line-height:1.7;white-space:pre-wrap}.cv-edit-footer{display:flex;justify-content:flex-end;gap:10px;border-top:1px solid var(--line);padding-top:18px}@media(max-width:1100px){.cv-application-row{flex-wrap:wrap}.cv-application-row>.cv-actions{margin-left:62px}}@media(max-width:550px){.cv-application-row{padding:18px;gap:12px}.cv-person-avatar{display:none}.cv-application-row>.cv-actions{margin-left:0;width:100%}.cv-application-meta{min-width:100px}.cv-edit-body{padding:18px}}

.cv-department-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:16px;margin-top:24px}.cv-department-card{display:grid;gap:12px;text-align:left;padding:24px;background:var(--rail);color:var(--text);border:1px solid var(--line);border-radius:14px;cursor:pointer;font:inherit}.cv-department-card:hover{border-color:#8b7cff;background:var(--hover)}.cv-department-card svg,.cv-department-link{color:#8b7cff}.cv-department-link{font-size:13px}.cv-back{margin-top:20px}.cv-actions{display:flex;gap:10px;flex-wrap:wrap}.cv-preview-dialog{width:min(1100px,94vw);max-width:94vw;height:88vh;max-height:92vh;padding:0;border:1px solid var(--line);border-radius:14px;background:var(--bg);color:var(--text)}.cv-preview-dialog::backdrop{background:#0009}.cv-preview-dialog[open]{display:flex;flex-direction:column}.cv-preview-heading{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:16px 20px;border-bottom:1px solid var(--line)}.cv-preview-heading h3{margin:0 0 5px}.cv-preview-dialog iframe{width:100%;flex:1;min-height:0;border:0;background:white}

.cv-workspace{max-width:1400px;margin:auto;padding:36px 28px 64px}.cv-heading,.cv-section-heading,.cv-candidate{display:flex;justify-content:space-between;align-items:center;gap:24px}.cv-heading{margin-bottom:30px}.cv-heading h1{font-size:30px;margin:8px 0}.cv-heading p,.cv-section-heading p{margin:8px 0}.cv-layout{display:grid;grid-template-columns:210px minmax(0,1fr);gap:28px}.cv-nav{align-self:start;border:1px solid var(--line);border-radius:14px;padding:12px;display:grid;gap:6px}.cv-nav button,.cv-nav a{padding:12px;text-align:left;border:0;background:transparent;color:inherit;text-decoration:none;border-radius:8px;display:flex;justify-content:space-between;font:inherit;cursor:pointer}.cv-nav button.active{background:#7563e824;color:#9585ff}.cv-card{border:1px solid var(--line);border-radius:14px;background:var(--rail);padding:22px;margin-top:18px}.cv-content{min-width:0}.cv-content h2{margin:0;font-size:23px}.cv-content h3{margin:0 0 8px;font-size:16px}.cv-fields,.cv-review{display:grid;grid-template-columns:1fr 1fr;gap:18px}.cv-review{grid-template-columns:180px 1fr auto;align-items:end;border-top:1px solid var(--line);padding-top:18px;margin-top:20px}.cv-workspace label{display:grid;gap:8px;font-size:13px;font-weight:600}.cv-workspace input,.cv-workspace select,.cv-workspace textarea{width:100%;min-width:0;box-sizing:border-box;font:inherit;background:var(--bg);color:var(--text);border:1px solid var(--line);border-radius:8px;padding:11px 12px}.cv-job-form{display:grid;gap:20px}.cv-empty{text-align:center;padding:48px 24px}.cv-section-heading>input{max-width:300px}.cv-workspace .muted{font-size:14px;color:var(--muted,#999)}@media(max-width:850px){.cv-layout{grid-template-columns:1fr}.cv-nav{display:flex;flex-wrap:wrap}.cv-review{grid-template-columns:1fr 1fr}.cv-heading,.cv-section-heading{align-items:flex-start;flex-wrap:wrap}}@media(max-width:550px){.cv-workspace{padding:24px 16px}.cv-fields,.cv-review{grid-template-columns:1fr}.cv-candidate{align-items:flex