/* Compact job rows retain the full card presentation in grid view. */
.cv-jobs-list{gap:10px}.cv-jobs-list .cv-job-card{grid-template-columns:110px minmax(180px,1fr) 140px auto;gap:16px;padding:15px 18px}.cv-jobs-list .cv-job-card-heading{justify-content:flex-start}.cv-jobs-list .cv-job-icon{display:none}.cv-jobs-list .cv-job-department{font-size:10px;margin-bottom:5px}.cv-jobs-list .cv-job-summary h3{font-size:15px;margin:0}.cv-jobs-list .cv-job-description{display:none}.cv-jobs-list .cv-job-facts{gap:6px;font-size:11px}.cv-jobs-list .cv-job-footer{grid-column:auto;border:0;padding:0;gap:12px;flex-wrap:wrap;justify-content:flex-end}.cv-jobs-list .cv-job-footer .button{padding:7px 10px;font-size:12px}.cv-jobs-list .cv-job-link{font-size:12px}@media(max-width:1050px){.cv-jobs-list .cv-job-card{grid-template-columns:95px minmax(150px,1fr) auto}.cv-jobs-list .cv-job-facts{display:none}.cv-jobs-list .cv-job-footer{grid-column:auto}}@media(max-width:550px){.cv-jobs-list .cv-job-card{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;padding:14px}.cv-jobs-list .cv-job-summary{grid-column:1;grid-row:1}.cv-jobs-list .cv-job-card-heading{grid-column:2;grid-row:1;justify-content:flex-end}.cv-jobs-list .cv-job-footer{grid-column:1/-1;justify-content:space-between}}
.cv-modal-close{display:grid;place-items:center;flex-shrink:0;width:34px;height:34px;padding:0;border:0;border-radius:8px;background:transparent;color:var(--muted);cursor:pointer}.cv-modal-close:hover{background:var(--hover);color:var(--text)}.cv-modal-close:focus-visible{outline:2px solid #9585ff;outline-offset:2px}
